import{c as l,Q as a,j as n,m as s}from"./chunks/framework.DOi4mjdC.js";const p="/assets/TIK2%E7%9F%A2%E9%87%8F%E7%BC%96%E7%A8%8B%E6%B5%81%E7%A8%8B.C0Edq0Co.png",_=JSON.parse('{"title":"算子实现","description":"","frontmatter":{},"headers":[{"level":1,"title":"算子实现","slug":"算子实现"},{"level":2,"title":"算子分析与核函数定义","slug":"算子分析与核函数定义"},{"level":2,"title":"Host侧线程切分计算","slug":"host侧线程切分计算"},{"level":2,"title":"Kernel侧算子实现","slug":"kernel侧算子实现"},{"level":2,"title":"运行验证","slug":"运行验证"}],"relativePath":"guide/算子实践参考/SIMT算子实现/算子实现.md","filePath":"guide/算子实践参考/SIMT算子实现/算子实现.md"}'),o={name:"guide/算子实践参考/SIMT算子实现/算子实现.md"};function e(i,t,u,g,d,c){return a(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="算子实现" tabindex="-1">算子实现 <a class="header-anchor" href="#算子实现" aria-label="Permalink to &quot;算子实现&quot;">​</a></h1><p>本章节将以Gather类算子为例，介绍SIMT算子实现的基本流程，如下图所示：</p><p><img src="'+p+`" alt=""></p><ul><li>算子分析与核函数定义：明确算子的输入和输出，分析最大线程数的设置方案。明确算子核函数名、输入输出参数，确定动态参数空间大小，配置最大线程数。</li><li>Host侧线程切分计算：根据输入数据的shape信息，计算和设置gridDim、blockDim等参数。</li><li>Kernel侧算子实现：实现单线程内的计算逻辑。</li></ul><p>下文将对上述步骤进行详细介绍。完整的算子实现请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/03_simt_api/02_features/00_resource_management/general_gather" target="_blank" rel="noreferrer">gather算子实现样例</a>。</p><h2 id="算子分析与核函数定义" tabindex="-1">算子分析与核函数定义 <a class="header-anchor" href="#算子分析与核函数定义" aria-label="Permalink to &quot;算子分析与核函数定义&quot;">​</a></h2><p>算子分析具体步骤如下：</p><ol><li><p>明确算子的功能和计算逻辑。</p><p>gather算子的功能为从输入张量中获取指定索引行的数据，即从形状为M * N的二维向量input中获取指定索引的m行数据，这m行的行索引由输入index指定。算子输出output第i行数据的计算公式为：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>output[i] = input[index[i]]</span></span></code></pre></div></li><li><p>明确算子的输入和输出。</p><ul><li>gather算子有两个输入：input与index；输出为output。</li><li>本样例中算子输入input的数据类型支持float、half、int32_t，index的数据类型为uint32_t，算子输出的数据类型与输入的数据类型相同。</li><li>每个线程处理一行数据，需要传入每行数据的长度in_width以及需要处理的总行数index_total_length，以确保尾部线程不会进行无效操作。</li><li>在算子实现中，无需使用大量临时变量，为了提高性能，可以在默认最大线程数（1024）的基础上适当增大核函数的最大线程数。</li></ul></li><li><p>明确函数名称和参数。</p><ul><li><p>自定义核函数名称，本样例中核函数命名为gather_custom。</p></li><li><p>通过分析算子的输入和输出，使用模板参数来支持不同的输入输出数据类型。</p><p>&lt;table&gt;&lt;thead align=&quot;left&quot;&gt;&lt;tr&gt;&lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;31.619999999999997%&quot;&gt;&lt;p&gt;模板参数名&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;29.2%&quot;&gt;&lt;p&gt;模板参数类型&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;39.18%&quot;&gt;&lt;p&gt;参数定义&lt;/p&gt; &lt;/th&gt; &lt;/tr&gt; &lt;/thead&gt; &lt;tbody&gt;&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;31.619999999999997%&quot;&gt;&lt;p&gt;type_data&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;29.2%&quot;&gt;&lt;p&gt;typename&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;39.18%&quot;&gt;&lt;p&gt;输入输出的数据类型&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;31.619999999999997%&quot;&gt;&lt;p&gt;type_idx&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;29.2%&quot;&gt;&lt;p&gt;typename&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;39.18%&quot;&gt;&lt;p&gt;index的数据类型&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p><p>函数入参定义如下：</p><p>&lt;table&gt;&lt;thead align=&quot;left&quot;&gt;&lt;tr&gt;&lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;23.362336233623363%&quot;&gt;&lt;p&gt;参数名&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;17.72177217721772%&quot;&gt;&lt;p&gt;参数类型&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;58.91589158915891%&quot;&gt;&lt;p&gt;参数定义&lt;/p&gt; &lt;/th&gt; &lt;/tr&gt; &lt;/thead&gt; &lt;tbody&gt;&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;23.362336233623363%&quot;&gt;&lt;p&gt;input&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;17.72177217721772%&quot;&gt;&lt;p&gt;type_data*&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;58.91589158915891%&quot;&gt;&lt;p&gt;输入数据在&lt;span&gt;Global Memory&lt;/span&gt;上的内存地址&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;23.362336233623363%&quot;&gt;&lt;p&gt;index&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;17.72177217721772%&quot;&gt;&lt;p&gt;type_idx*&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;58.91589158915891%&quot;&gt;&lt;p&gt;索引数据在&lt;span&gt;Global Memory&lt;/span&gt;上的内存地址&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;23.362336233623363%&quot;&gt;&lt;p&gt;gather_output&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;17.72177217721772%&quot;&gt;&lt;p&gt;type_data*&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;58.91589158915891%&quot;&gt;&lt;p&gt;输出数据在&lt;span&gt;Global Memory&lt;/span&gt;上的内存地址&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;23.362336233623363%&quot;&gt;&lt;p&gt;in_width&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;17.72177217721772%&quot;&gt;&lt;p&gt;uint32_t&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;58.91589158915891%&quot;&gt;&lt;p&gt;输入数据第二维的长度（列宽）&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;23.362336233623363%&quot;&gt;&lt;p&gt;index_total_length&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;17.72177217721772%&quot;&gt;&lt;p&gt;uint32_t&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;58.91589158915891%&quot;&gt;&lt;p&gt;index数据的总长度&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p></li></ul></li><li><p>明确SIMT核函数gridDim、blockDim等动态参数设置方案。</p><ul><li>本样例采用均匀切分方案，根据可用核数和最大线程数的限制，计算和调整gridDim（启用的线程块的个数）、blockDim（一个线程块启用的的线程个数），同时保证gridDim不超过65535、blockDim不超过最大线程数2048。</li><li>本算子实现逻辑中无需使用动态UB空间。</li></ul></li></ol><p>通过以上分析，得到SIMT Gather算子的设计规格如下：</p><ul><li><p>算子类型（OpType）：Gather</p></li><li><p>算子输入输出：</p><p><strong>表 1</strong> Gather算子输入输出规格</p><p>&lt;table&gt;&lt;thead align=&quot;left&quot;&gt;&lt;tr&gt;&lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;&lt;strong&gt;name&lt;/strong&gt;&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;&lt;strong&gt;shape&lt;/strong&gt;&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;&lt;strong&gt;data type&lt;/strong&gt;&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;&lt;strong&gt;format&lt;/strong&gt;&lt;/p&gt; &lt;/th&gt; &lt;/tr&gt; &lt;/thead&gt; &lt;tbody&gt;&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;input（输入）&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;(M, N)&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;float/half/int32_t&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;ND&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;index（输入）&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;(m), m &lt; M&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;uint32_t&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;ND&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;output（输出）&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;(m, N)&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;float/half/int32_t&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;ND&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p></li><li><p>核函数名称：gather_custom</p></li></ul><p>核函数定义如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>constexpr uint32_t MAX_THREAD_COUNT = 2048;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>template &lt;typename type_data, typename type_idx&gt;</span></span>
<span class="line"><span>__global__ __launch_bounds__(MAX_THREAD_COUNT) void gather_custom(</span></span>
<span class="line"><span>    type_data* input,</span></span>
<span class="line"><span>    type_idx* index,</span></span>
<span class="line"><span>    type_data* gather_output,</span></span>
<span class="line"><span>    uint32_t in_width,</span></span>
<span class="line"><span>    uint32_t index_total_length)</span></span></code></pre></div><div class="note custom-block github-alert"><p class="custom-block-title">说明</p><p>在定义核函数时，使用__launch_bounds__(MAX_THREAD_COUNT)来指定最大线程数。最大线程数的设置范围为1到2048。设置的最大线程数越大，支持启用的线程越多，性能越好，但每个线程可使用的内部寄存器数量会减少。若未设置，最大线程数默认值为1024。在上述分析中已明确计算不需要过多寄存器，因此设置最大线程数为2048。在实际的算子开发过程中，应根据具体的算子实现来调整该值。</p></div><h2 id="host侧线程切分计算" tabindex="-1">Host侧线程切分计算 <a class="header-anchor" href="#host侧线程切分计算" aria-label="Permalink to &quot;Host侧线程切分计算&quot;">​</a></h2><p>本样例以简单的均匀切分方案介绍如何实现动态切分参数的计算。</p><ol><li><p>设置初始gridDim。</p><p>考虑到如果gridDim设置得比实际AIV核数少，会导致空闲核浪费，因此将初始gridDim设置为当前芯片的实际AIV核数量。AIV数量的获取方法如下所示：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>uint32_t real_core_num = 0;</span></span>
<span class="line"><span>const auto&amp; platformInfoMgr = platform_ascendc::PlatformAscendCManager::GetInstance();</span></span>
<span class="line"><span>real_core_num = platformInfoMgr-&gt;GetCoreNumAiv();</span></span>
<span class="line"><span>block_num = real_core_num; // block_num为初始gridDim</span></span></code></pre></div></li><li><p>计算blockDim。</p><p>根据输入index的长度index_total_length、初始gridDim计算一个线程块启用的的线程个数blockDim。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// thread_num_per_block为blockDim值</span></span>
<span class="line"><span>thread_num_per_block = (index_total_length + block_num - 1) / block_num;</span></span></code></pre></div></li><li><p>调整blockDim。</p><p>若blockDim超出最大线程数限制，调整blockDim值为最大线程数值。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>if (thread_num_per_block &gt; MAX_THREAD_COUNT) {</span></span>
<span class="line"><span>    thread_num_per_block = MAX_THREAD_COUNT;</span></span>
<span class="line"><span>}</span></span></code></pre></div></li><li><p>调整gridDim。</p><p>重新计算gridDim，确保gridDim * blockDim &gt; index_total_length，即确保所有启用的线程能够处理完指定行数的数据。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>block_num = (index_total_length + thread_num_per_block - 1) / thread_num_per_block;</span></span></code></pre></div></li></ol><p>完整的切分计算代码如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>constexpr uint32_t MAX_THREAD_COUNT = 2048;</span></span>
<span class="line"><span>constexpr uint32_t MAX_BLOCK_COUNT = 65535;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>bool block_split(uint32_t index_total_length, uint32_t &amp;block_num, uint32_t &amp;thread_num_per_block) {</span></span>
<span class="line"><span>    uint32_t real_core_num = 0;</span></span>
<span class="line"><span>    const auto&amp; platformInfoMgr = platform_ascendc::PlatformAscendCManager::GetInstance();</span></span>
<span class="line"><span>    if (platformInfoMgr == nullptr) {</span></span>
<span class="line"><span>        std::cout &lt;&lt; &quot;[ERROR] Get platform info failed, please check device status.&quot;&lt;&lt; std::endl;</span></span>
<span class="line"><span>        return false;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    real_core_num = platformInfoMgr-&gt;GetCoreNumAiv();</span></span>
<span class="line"><span>    block_num = real_core_num;</span></span>
<span class="line"><span>    thread_num_per_block = (index_total_length + block_num -1) / block_num;</span></span>
<span class="line"><span>    if (thread_num_per_block &gt; MAX_THREAD_COUNT) {</span></span>
<span class="line"><span>        thread_num_per_block = MAX_THREAD_COUNT;</span></span>
<span class="line"><span>        block_num = (index_total_length + thread_num_per_block - 1) / thread_num_per_block;</span></span>
<span class="line"><span>        if (block_num &gt; MAX_BLOCK_COUNT) {</span></span>
<span class="line"><span>        std::cout &lt;&lt; &quot;[ERROR] index_total_length: &quot;&lt;&lt; index_total_length &lt;&lt; &quot; can not be bigger than &quot;</span></span>
<span class="line"><span>            &lt;&lt; MAX_THREAD_COUNT * MAX_BLOCK_COUNT&lt;&lt; &quot;.&quot;&lt;&lt; std::endl;</span></span>
<span class="line"><span>        return false;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    return true;</span></span>
<span class="line"><span>}</span></span></code></pre></div><h2 id="kernel侧算子实现" tabindex="-1">Kernel侧算子实现 <a class="header-anchor" href="#kernel侧算子实现" aria-label="Permalink to &quot;Kernel侧算子实现&quot;">​</a></h2><ol><li><p>根据均匀切分算法，获取当前线程的位置偏移量。</p><p>在本算子中，仅使用gridDim、blockDim等线程维度的第一维，因此计算偏移量时只需考虑x维信息。如下代码所示，threadIdx表示线程在其所在线程块内的索引，blockDim表示一个线程块中设置的线程数，而blockIdx表示线程块的索引。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 计算线程索引</span></span>
<span class="line"><span>int32_t out_row = blockIdx.x * blockDim.x + threadIdx.x;</span></span></code></pre></div></li><li><p>根据线程索引，获取当前线程需要处理数据的行索引，计算对应的输入、输出位置偏移量，实现整行数据的获取采集。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>uint32_t in_row = index[out_row];</span></span>
<span class="line"><span>int input_idx = in_row * in_width;</span></span>
<span class="line"><span>int output_idx = out_row * in_width;</span></span>
<span class="line"><span>for (int32_t col = 0; col &lt; in_width; col++) {</span></span>
<span class="line"><span>    gather_output[output_idx] = input[input_idx];</span></span>
<span class="line"><span>    input_idx += 1;</span></span>
<span class="line"><span>    output_idx += 1;</span></span>
<span class="line"><span>}</span></span></code></pre></div></li></ol><p>完整的核函数功能代码如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>constexpr uint32_t MAX_THREAD_COUNT = 2048;</span></span>
<span class="line"><span>constexpr uint32_t MAX_BLOCK_COUNT = 65535;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>template &lt;typename type_data, typename type_idx&gt;</span></span>
<span class="line"><span>__global__ __launch_bounds__(MAX_THREAD_COUNT) void gather_custom(</span></span>
<span class="line"><span>    type_data* input,</span></span>
<span class="line"><span>    type_idx* index,</span></span>
<span class="line"><span>    type_data* gather_output,</span></span>
<span class="line"><span>    uint32_t in_width,</span></span>
<span class="line"><span>    uint32_t index_total_length)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    // Calculate global thread ID</span></span>
<span class="line"><span>    int32_t out_row = blockIdx.x * blockDim.x + threadIdx.x;</span></span>
<span class="line"><span>    // Maps to the row index of output tensor</span></span>
<span class="line"><span>    if (out_row &gt;= index_total_length) {</span></span>
<span class="line"><span>        return;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    // Single thread processes entire row (all columns) - enables coalesced memory access</span></span>
<span class="line"><span>    uint32_t in_row = index[out_row];</span></span>
<span class="line"><span>    int input_idx = in_row * in_width;</span></span>
<span class="line"><span>    int output_idx = out_row * in_width;</span></span>
<span class="line"><span>    for (int32_t col = 0; col &lt; in_width; col++) {</span></span>
<span class="line"><span>        gather_output[output_idx] = input[input_idx];</span></span>
<span class="line"><span>        input_idx += 1;</span></span>
<span class="line"><span>        output_idx += 1;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><h2 id="运行验证" tabindex="-1">运行验证 <a class="header-anchor" href="#运行验证" aria-label="Permalink to &quot;运行验证&quot;">​</a></h2><p>核函数即算子Kernel程序开发完成后，即可编写Host侧的核函数调用程序，实现从Host侧的APP程序调用算子，进行运行验证。</p><p>Host侧的关键代码如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>std::vector&lt;float&gt; gather(std::vector&lt;float&gt;&amp; input, const uint32_t* in_shape, std::vector&lt;uint32_t&gt;&amp; index)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    ...</span></span>
<span class="line"><span>    // 计算切分参数，设置动态UB内存</span></span>
<span class="line"><span>   </span></span>
<span class="line"><span>    uint32_t block_num = 0;</span></span>
<span class="line"><span>    uint32_t thread_num_per_block = 0;</span></span>
<span class="line"><span>    block_split(index_total_length, block_num, thread_num_per_block);</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    ...</span></span>
<span class="line"><span>    // 计算切分参数，设置动态UB内存</span></span>
<span class="line"><span>    uint32_t dyn_ubuf_size = 0;  // No need to alloc dynamic memory.</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    // 用内存调用符&lt;&lt;&lt;...&gt;&gt;&gt;调用核函数完成指定的运算</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    gather_custom&lt;&lt;&lt;block_num, thread_num_per_block, dyn_ubuf_size, stream&gt;&gt;&gt;(</span></span>
<span class="line"><span>              input_device, index_device, output_device, in_shape[1], index_total_length);</span></span>
<span class="line"><span>    ...</span></span>
<span class="line"><span>}</span></span></code></pre></div>`,26)])])}const q=l(o,[["render",e]]);export{_ as __pageData,q as default};
